import{_ as e}from"./chunks/window_compare.DHGd22N_.js";import{_ as a,o as n,c as o,ao as s}from"./chunks/framework.WV2gjn07.js";const m=JSON.parse('{"title":"The window","description":"","frontmatter":{},"headers":[],"relativePath":"manual/window.md","filePath":"manual/window.md","lastUpdated":null}'),l={name:"manual/window.md"};function i(r,t,d,p,h,g){return n(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="The-window" tabindex="-1">The window <a class="header-anchor" href="#The-window" aria-label="Permalink to &quot;The window {#The-window}&quot;">​</a></h1><p>The window has a row of controls at the top, a column of data panels on the left, and the plot area on the right.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────┬───────────────────┬─────────────────┬──────────┐</span></span>
<span class="line"><span>│ Menu         │ Picking           │ Picks           │ logo     │</span></span>
<span class="line"><span>│              │ toggle, user name │ Compare Picks   │          │</span></span>
<span class="line"><span>├──────────────┼───────────────────┴─────────────────┴──────────┤</span></span>
<span class="line"><span>│ Volume data  │ topography axis                                │</span></span>
<span class="line"><span>│ Surface data ├────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Point data   │ profile axis                                   │</span></span>
<span class="line"><span>│ Topography   │ (volume data, surfaces, points, picks)         │</span></span>
<span class="line"><span>│ Compare picks│                                                │</span></span>
<span class="line"><span>│ Map overview ├────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Screenshot   │ colorbars and legends                          │</span></span>
<span class="line"><span>└──────────────┴────────────────────────────────────────────────┘</span></span></code></pre></div><p><img src="`+e+'" alt=""></p><h2 id="Top-row" tabindex="-1">Top row <a class="header-anchor" href="#Top-row" aria-label="Permalink to &quot;Top row {#Top-row}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Element</th><th style="text-align:left;">What it does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Menu</strong></td><td style="text-align:left;">Dropdown with all file actions: load a profile, save and load picks, states and screenshots, close the window. See <a href="/AdriaArrayGeometryPicker.jl/previews/PR23/manual/window#The-menu">The menu</a>.</td></tr><tr><td style="text-align:left;"><strong>Picking</strong> toggle</td><td style="text-align:left;">Switches picking on (green) and off (red). Picks can only be added, moved or removed while it is on. See <a href="/AdriaArrayGeometryPicker.jl/previews/PR23/manual/picking#Picking">Picking</a>.</td></tr><tr><td style="text-align:left;"><strong>User name</strong> field</td><td style="text-align:left;">Your name or initials. It is stored with the picks you save. Type the name and press Enter.</td></tr><tr><td style="text-align:left;"><strong>Compare Picks</strong> toggle</td><td style="text-align:left;">Shows or hides all picks loaded with <strong>Load Compare Picks</strong>. See <a href="/AdriaArrayGeometryPicker.jl/previews/PR23/manual/compare#Comparing-picks">Comparing picks</a>.</td></tr></tbody></table><h2 id="The-menu" tabindex="-1">The menu <a class="header-anchor" href="#The-menu" aria-label="Permalink to &quot;The menu {#The-menu}&quot;">​</a></h2><p>Click <strong>Menu</strong> and choose an entry. Each entry opens a file dialog where needed.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Entry</th><th style="text-align:left;">Action</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Load Profile</strong></td><td style="text-align:left;">Open a GMG profile (<code>.pgmg</code>).</td></tr><tr><td style="text-align:left;"><strong>Save State</strong></td><td style="text-align:left;">Save the path of the profile, the settings of the window and the picks (<code>.aagps</code>).</td></tr><tr><td style="text-align:left;"><strong>Load State</strong></td><td style="text-align:left;">Restore a saved state (<code>.aagps</code>, or a <code>.jld2</code> state file of MakiePickerGUI.jl).</td></tr><tr><td style="text-align:left;"><strong>Save Picks</strong></td><td style="text-align:left;">Save the picks to a <code>.aagpp</code> (JLD2) or <code>.csv</code> file.</td></tr><tr><td style="text-align:left;"><strong>Load Picks</strong></td><td style="text-align:left;">Load picks from a file, so that you can edit them. Only picks of the loaded profile are accepted.</td></tr><tr><td style="text-align:left;"><strong>Load Compare Picks</strong></td><td style="text-align:left;">Show the picks of another file (for example of another person) as a dashed line. They cannot be edited.</td></tr><tr><td style="text-align:left;"><strong>Save Screenshot</strong></td><td style="text-align:left;">Save an image (PNG) of the whole window.</td></tr><tr><td style="text-align:left;"><strong>Close</strong></td><td style="text-align:left;">Close the window.</td></tr></tbody></table><p>The file dialogs do not block the window: it keeps drawing while a dialog is open. Messages about what was loaded or saved, and any errors, appear in the REPL (or the terminal), not in the window.</p><h2 id="Plot-area" tabindex="-1">Plot area <a class="header-anchor" href="#Plot-area" aria-label="Permalink to &quot;Plot area {#Plot-area}&quot;">​</a></h2><p>The plot area shows the loaded profile:</p><ul><li><p>The <strong>topography axis</strong> at the top shows the elevation along the profile. Its title is the name of the profile file. The coordinates (longitude, latitude) of the start and end point of the profile are written in its corners. The start is marked <strong>A</strong>, the end <strong>B</strong>, as on the map overview.</p></li><li><p>The <strong>profile axis</strong> below it shows the volume data as a heatmap, with contour lines, surface lines, seismicity markers, your picks (white circles) and compared picks (dashed lines). The x axis is the distance along the profile (km) and the y axis is the depth (km, negative downward).</p></li><li><p>Below, the <strong>colorbars</strong> of the heatmap and the contour lines and the <strong>legends</strong> of the surface data, the point data and the compared picks.</p></li></ul><p>The topography axis and the profile axis are linked in x: zooming in one zooms the other.</p><p>For a horizontal slice the plot area looks different; see <a href="/AdriaArrayGeometryPicker.jl/previews/PR23/manual/horizontal#Horizontal-slices">Horizontal slices</a>.</p><h3 id="Zooming-and-panning" tabindex="-1">Zooming and panning <a class="header-anchor" href="#Zooming-and-panning" aria-label="Permalink to &quot;Zooming and panning {#Zooming-and-panning}&quot;">​</a></h3><p>The axes use the standard <a href="https://docs.makie.org/stable/reference/blocks/axis#Axis-interaction" target="_blank" rel="noreferrer">Makie axis interactions</a>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Mouse / keys</th><th style="text-align:left;">Action</th></tr></thead><tbody><tr><td style="text-align:left;">scroll wheel</td><td style="text-align:left;">zoom in and out around the mouse</td></tr><tr><td style="text-align:left;">scroll wheel while holding <strong>X</strong> or <strong>Y</strong></td><td style="text-align:left;">zoom only in x or only in y</td></tr><tr><td style="text-align:left;">right button drag</td><td style="text-align:left;">pan</td></tr><tr><td style="text-align:left;">left button drag (not on a pick)</td><td style="text-align:left;">zoom into the rectangle</td></tr><tr><td style="text-align:left;"><strong>Ctrl</strong> + left click</td><td style="text-align:left;">reset the zoom</td></tr></tbody></table><p>While picking is on, a left click <em>on a pick</em> starts moving that pick instead of zooming (see <a href="/AdriaArrayGeometryPicker.jl/previews/PR23/manual/picking#Picking">Picking</a>).</p><h2 id="Panels-on-the-left" tabindex="-1">Panels on the left <a class="header-anchor" href="#Panels-on-the-left" aria-label="Permalink to &quot;Panels on the left {#Panels-on-the-left}&quot;">​</a></h2><p>The column on the left holds the panels that control what the plot area shows. Each panel has a blue header with a toggle on the right. Switch the toggle on to expand the panel. Only one panel is expanded at a time: expanding a panel collapses the one that was open before.</p><p>The panels are described in <a href="./panels">Data panels</a>.</p>',22)])])}const w=a(l,[["render",i]]);export{m as __pageData,w as default};
